#include <memory>
#include <iostream>

class Resource {};

class ClassB {
private:
    std::auto_ptr<Resource> ptr;
public:
    ClassB() : ptr(new Resource()) {}

    // Required Custom Copy Constructor for Deep Copy
    ClassB(const ClassB& x) 
    : ptr(new Resource(*x.ptr)) {}

    // Required Custom Assignment Operator
    ClassB& operator=(const ClassB& x) {
        if (this != &x) {
            // Resource management via auto_ptr destructor/assignment
            ptr.reset(new Resource(*x.ptr));
        }
        return *this;
    }
    // Default operations would have caused ownership transfer.
};
